import{_ as a,H as e,f as n,i}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"04 | 如何快速搭建Prometheus系统？","description":"","frontmatter":{},"headers":[{"level":2,"title":"通用架构回顾","slug":"通用架构回顾","link":"#通用架构回顾","children":[]},{"level":2,"title":"部署 Prometheus","slug":"部署-prometheus","link":"#部署-prometheus","children":[]},{"level":2,"title":"部署 Node-Exporter","slug":"部署-node-exporter","link":"#部署-node-exporter","children":[]},{"level":2,"title":"配置告警规则","slug":"配置告警规则","link":"#配置告警规则","children":[]},{"level":2,"title":"部署 Alertmanager","slug":"部署-alertmanager","link":"#部署-alertmanager","children":[]},{"level":2,"title":"部署 Grafana","slug":"部署-grafana","link":"#部署-grafana","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"互动时刻","slug":"互动时刻","link":"#互动时刻","children":[]}],"relativePath":"运维监控系统实战笔记/04｜如何快速搭建Prometheus系统？.md","filePath":"运维监控系统实战笔记/04｜如何快速搭建Prometheus系统？.md","lastUpdated":1795561216000}'),t={name:"运维监控系统实战笔记/04｜如何快速搭建Prometheus系统？.md"};function p(l,s,r,h,o,c){return e(),n("div",null,[...s[0]||(s[0]=[i(`<h1 id="_04-如何快速搭建prometheus系统" tabindex="-1">04 | 如何快速搭建Prometheus系统？ <a class="header-anchor" href="#_04-如何快速搭建prometheus系统" aria-label="Permalink to &quot;04 | 如何快速搭建Prometheus系统？&quot;">​</a></h1><p>你好，我是秦晓辉。</p><p>前面三讲我们介绍了监控系统的一些基本概念，这一讲我们开始进入实操环节，部署监控系统。业界可选的开源方案很多，随着云原生的流行，越来越多的公司开始拥抱云原生，而云原生标配的监控系统显然就是 Prometheus，而且 Prometheus 的部署非常简单，所以这一讲我们就先来自己动手搭建 Prometheus。</p><h2 id="通用架构回顾" tabindex="-1">通用架构回顾 <a class="header-anchor" href="#通用架构回顾" aria-label="Permalink to &quot;通用架构回顾&quot;">​</a></h2><p>还记得我们上一讲介绍的监控系统通用架构吗？我们可以回顾一下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/04/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/04/1.png" alt=""></a></p><p>之所以说 Prometheus 比较容易搭建，是因为它把服务端组件，包括时序库、告警引擎、数据展示三大块，整合成了一个进程，组件的数量大幅减少。Prometheus 生态的采集器就是各种Exporter，告警发送靠的是 AlertManager 组件，下面我们先来部署 Prometheus 模块。</p><h2 id="部署-prometheus" tabindex="-1">部署 Prometheus <a class="header-anchor" href="#部署-prometheus" aria-label="Permalink to &quot;部署 Prometheus&quot;">​</a></h2><p>因为生产环境大概率是 Linux 的，所以我们选择 Linux 下的发布包，把 Prometheus 和Alertmanager 两个包都下载下来。</p><p>注：Prometheus 的下载地址：<a href="https://prometheus.io/download/" target="_blank" rel="noreferrer">https://prometheus.io/download/</a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/04/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/04/2.png" alt=""></a></p><p>下载之后解压缩，使用 systemd 托管启动，你可以参考下面的命令。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/prometheus</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wget</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/prometheus/prometheus/releases/download/v2.37.1/prometheu</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prometheus-2.37.1.linux-amd64.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -far</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prometheus-2.37.1.linux-amd64/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  /opt/prometheus/</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># service</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">​EOF</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/etc/systemd/system/prometheus.service</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[Unit]</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Description=&quot;prometheus&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Documentation=https://prometheus.io/</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">After=network.target</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[Service]</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Type=simple</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ExecStart=/opt/prometheus/prometheus  --config.file=/opt/prometheus/prometheus.ym</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Restart=on-failure</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">SuccessExitStatus=0</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">LimitNOFILE=65536</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">StandardOutput=syslog</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">StandardError=syslog</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">SyslogIdentifier=prometheus</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[Install]</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">WantedBy=multi-user.target</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">EOF</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">systemctl enable prometheus</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">systemctl start prometheus</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">systemctl status prometheus</span></span></code></pre></div><p>这里需要重点关注的是 Prometheus 进程的启动参数，我在每个参数下面都做出了解释，你可以看一下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>--config.file=/opt/prometheus/prometheus.yml</span></span>
<span class="line"><span>指定 Prometheus 的配置文件路径</span></span>
<span class="line"><span>--storage.tsdb.path=/opt/prometheus/data</span></span>
<span class="line"><span>指定 Prometheus 时序数据的硬盘存储路径</span></span>
<span class="line"><span>--web.enable-lifecycle</span></span>
<span class="line"><span>启用生命周期管理相关的 API，比如调用 /-/reload 接口就需要启用该项</span></span>
<span class="line"><span>--enable-feature=remote-write-receiver</span></span>
<span class="line"><span>启用 remote write 接收数据的接口，启用该项之后，categraf、grafana-agent 等 agent 就可以通</span></span>
<span class="line"><span>--query.lookback-delta=2m</span></span></code></pre></div><ul><li>即时查询在查询当前最新值的时候，只要发现这个参数指定的时间段内有数据，就取最新的那个点返回，这个时</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>--web.enable-admin-api</span></span>
<span class="line"><span>启用管理性 API，比如删除时间序列数据的 /api/v1/admin/tsdb/delete_series 接口</span></span></code></pre></div><p>如果正常启动，Prometheus 默认会在 9090 端口监听，访问这个端口就可以看到 Prometheus的 Web 页面，输入下面的 PromQL 可以查到一些监控数据。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/04/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/04/3.png" alt=""></a></p><p>这个数据是从哪里来的呢？其实是 Prometheus 自己抓取自己的，Prometheus 会在</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/metrics 接口暴露监控数据，你可以访问这个接口看一下输出。同时 Prometheus 在配置文</span></span></code></pre></div><p>件里配置了抓取规则，打开 prometheus.yml 就可以看到了。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scrape_configs:</span></span>
<span class="line"><span> - job_name: &#39;prometheus&#39;</span></span>
<span class="line"><span>   static_configs:</span></span>
<span class="line"><span>   - targets: [&#39;localhost:9090&#39;]</span></span>
<span class="line"><span>localhost:9090 是暴露监控数据的地址，没有指定接口路径，默认使用 /metrics，没有指定</span></span>
<span class="line"><span>scheme，默认使用 HTTP，所以实际请求的是 http://localhost:9090/metrics。了</span></span></code></pre></div><p>解了 Prometheus 自监控的方式，下面我们来看一下机器监控。</p><h2 id="部署-node-exporter" tabindex="-1">部署 Node-Exporter <a class="header-anchor" href="#部署-node-exporter" aria-label="Permalink to &quot;部署 Node-Exporter&quot;">​</a></h2><p>Prometheus 生态的机器监控比较简单，就是在所有的目标机器上部署 Node-Exporter，然后在抓取规则中给出所有 Node-Exporter 的地址就可以了。</p><p>首先，下载 Node-Exporter。你可以选择当下比较稳定的版本 1.3.1，下载之后解压就可以直接运行了，比如使用 nohup（生产环境建议使用 systemd 托管） 简单启动的话，可以输入下面这一行命令。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nohup ./node_exporter &amp;&gt; output.log &amp;</span></span></code></pre></div><p>Node-Exporter 默认的监听端口是 9100，我们可以通过下面的命令看到 Node-Exporter 采集的指标。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localhost:9100/metrics</span></span></code></pre></div><p>然后把 Node-Exporter 的地址配置到 prometheus.yml 中即可。修改了配置之后，记得给</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Prometheus 发个 HUP 信号，让 Prometheus 重新读取配置：kill -HUP &lt;​prometheus</span></span>
<span class="line"><span>pid&gt;。最终 scrape_configs 部分变成下面这段内容。</span></span>
<span class="line"><span>scrape_configs:</span></span>
<span class="line"><span> - job_name: &#39;prometheus&#39;</span></span>
<span class="line"><span>   static_configs:</span></span>
<span class="line"><span>   - targets: [&#39;localhost:9090&#39;]</span></span>
<span class="line"><span> - job_name: &#39;node_exporter&#39;</span></span>
<span class="line"><span>   static_configs:</span></span>
<span class="line"><span>   - targets: [&#39;localhost:9100&#39;]</span></span></code></pre></div><p>其中 targets 是个数组，如果要监控更多机器，就在 targets 中写上多个 Node-Exporter 的地址，用逗号隔开。之后在 Prometheus 的 Web 上（菜单位置 Status -&gt; Targets），就可以看到相关的 Targets 信息了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/04/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/04/4.png" alt=""></a></p><p>在查询监控数据的框里输入 node，就会自动提示很多 node 打头的指标。这些指标都是Node-Exporter 采集的，选择其中某一个就可以查到对应的监控数据，比如查看不同硬盘分区的余量大小。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/04/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/04/5.png" alt=""></a></p><p>Node-Exporter 默认内置了很多 collector，比如 cpu、loadavg、filesystem 等，可以通过命令</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">行启动参数来控制这些 collector，比如要关掉某个 collector，使用 --no-collector.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;​name&gt;，如果要开启某个 collector，使用 --collector.&lt;​name&gt;。具体可以参考 Node-</span></span></code></pre></div><p>Exporter 的 README。Node-Exporter 默认采集几百个指标，有了这些数据，我们就可以演示告警规则的配置了。</p><h2 id="配置告警规则" tabindex="-1">配置告警规则 <a class="header-anchor" href="#配置告警规则" aria-label="Permalink to &quot;配置告警规则&quot;">​</a></h2><p>Prometheus 进程内置了告警判断引擎，prometheus.yml 中可以指定告警规则配置文件，默认配置中有个例子。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rule_files:</span></span>
<span class="line"><span> # - &quot;first_rules.yml&quot;</span></span>
<span class="line"><span> # - &quot;second_rules.yml&quot;</span></span></code></pre></div><p>我们可以把不同类型的告警规则拆分到不同的配置文件中，然后在 prometheus.yml 中引用。比如 Node-Exporter 相关的规则，我们命名为 node_exporter.yml，最终这个 rule_files 就变成了如下配置。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rule_files:</span></span>
<span class="line"><span> - &quot;node_exporter.yml&quot;</span></span></code></pre></div><p>我设计了一个例子，监控 Node-Exporter 挂掉以及内存使用率超过 1% 这两种情况。这里我故意设置了一个很小的阈值，确保能够触发告警。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>groups:</span></span>
<span class="line"><span>- name: node_exporter</span></span>
<span class="line"><span> rules:</span></span>
<span class="line"><span> - alert: HostDown</span></span>
<span class="line"><span>   expr: up{job=&quot;node_exporter&quot;} == 0</span></span>
<span class="line"><span>   for: 1m</span></span>
<span class="line"><span>   labels:</span></span>
<span class="line"><span>     severity: critical</span></span>
<span class="line"><span>   annotations:</span></span>
<span class="line"><span>     summary: Host down {​{ $labels.instance }​}</span></span>
<span class="line"><span> - alert: MemUtil</span></span>
<span class="line"><span>   expr: 100 - node_memory_MemAvailable_bytes / node_memory_MemTotal_bytes * 100</span></span>
<span class="line"><span>   for: 1m</span></span>
<span class="line"><span>   labels:</span></span>
<span class="line"><span>     severity: warn</span></span>
<span class="line"><span>   annotations:</span></span>
<span class="line"><span>     summary: Mem usage larger than 1%, instance:{​{ $labels.instance }​}</span></span></code></pre></div><p>最后，给 Prometheus 进程发个 HUP 信号，让它重新加载配置文件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kill -HUP \`pidof prometheus\`</span></span></code></pre></div><p>之后，我们就可以去 Prometheus 的 Web 上（Alerts 菜单）查看告警规则的判定结果了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/04/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/04/6.png" alt=""></a></p><p>我们从图中可以看出，告警分成 3 个状态，Inactive、Pending、Firing。HostDown 这个规则当前是 Inactive 状态，表示没有触发相关的告警事件，MemUtil 这个规则触发了一个事件，处于 Firing 状态。那什么是 Pending 状态呢？触发过阈值但是还没有满足持续时长（ for 关键字后面指定的时间段）的要求，就是 Pending 状态。比如 for 1m，就表示触发阈值的时间持续 1分钟才算满足条件，如果规则判定执行频率是 10 秒，就相当于连续 6 次都触发阈值才可以。</p><p>在页面上我们看到告警了，就是一个巨大的进步，如果我们还希望在告警的时候收到消息通知，比如邮件、短信等，就需要引入 AlertManager 组件了。</p><h2 id="部署-alertmanager" tabindex="-1">部署 Alertmanager <a class="header-anchor" href="#部署-alertmanager" aria-label="Permalink to &quot;部署 Alertmanager&quot;">​</a></h2><p>部署 Prometheus 的时候，我们已经顺便把 Alertmanager 的包下载下来了，下面我们就安装一下。安装过程很简单，把上面的 prometheus.service 拿过来改一下给 Alertmanager 使用即可，下面是我改好的 alertmanager.service。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Unit]</span></span>
<span class="line"><span>Description=&quot;alertmanager&quot;</span></span>
<span class="line"><span>After=network.target</span></span>
<span class="line"><span>[Service]</span></span>
<span class="line"><span>Type=simple</span></span>
<span class="line"><span>ExecStart=/usr/local/alertmanager/alertmanager</span></span>
<span class="line"><span>WorkingDirectory=/usr/local/alertmanager</span></span>
<span class="line"><span>Restart=on-failure</span></span>
<span class="line"><span>SuccessExitStatus=0</span></span>
<span class="line"><span>LimitNOFILE=65536</span></span>
<span class="line"><span>StandardOutput=syslog</span></span>
<span class="line"><span>StandardError=syslog</span></span>
<span class="line"><span>SyslogIdentifier=alertmanager</span></span>
<span class="line"><span>[Install]</span></span>
<span class="line"><span>WantedBy=multi-user.target</span></span></code></pre></div><p>我把 Alertmanager 解压到 /usr/local/alertmanager 目录，通过 ExecStart 可以看出，直接执行二进制就可以，实际 Alertmanager 会读取二进制同级目录下的 alertmanager.yml 配置文件。我使用 163 邮箱作为 SMTP 发件服务器，下面我们来看下具体的配置。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">global:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> smtp_from:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;username@163.com&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> smtp_smarthost:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;smtp.163.com:465&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> smtp_auth_username:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;username@163.com&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> smtp_auth_password:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;这里填写授权码&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> smtp_require_tls:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">route:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> group_by:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;alertname&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> group_wait:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 30s</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> group_interval:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1m</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> repeat_interval:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1h</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> receiver:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;email&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">receivers:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> -</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> name:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;web.hook&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">   webhook_configs:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">     -</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> url:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;http://127.0.0.1:5001/&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> -</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> name:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;email&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">   email_configs:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">   -</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> to:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;ulricqin@163.com&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">inhibit_rules:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> -</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> source_match:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">     severity:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;critical&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">   target_match:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">     severity:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;warning&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">   equal:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;alertname&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;dev&#39;,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;instance&#39;]</span></span></code></pre></div><p>首先配置一个全局 SMTP，然后修改 receivers。receivers 是个数组，默认例子里有个web.hook，我又加了一个 email 的 receiver，然后配置 route.receiver 字段的值为 email。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>email_configs 中的 to 表示收件人，多个人用逗号分隔，比如 to: &#39;user1@163.com,</span></span>
<span class="line"><span>user2@163.com&#39;，最后收到的邮件内容大概是这样的，你可以看一下我给出的样例。</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/04/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/04/7.png" alt=""></a></p><p>收到告警邮件，就说明这整个告警链路走通了。最后我们再看一下数据可视化的问题。Prometheus 自带的看图工具，是给专家用的，需要对指标体系非常了解，经验没法沉淀，而且绘图工具单一，只有折线图。如果你希望有一个更好用的 UI 工具，可以试试 Grafana。</p><h2 id="部署-grafana" tabindex="-1">部署 Grafana <a class="header-anchor" href="#部署-grafana" aria-label="Permalink to &quot;部署 Grafana&quot;">​</a></h2><p>Grafana 是一个数据可视化工具，有丰富的图表类型，视觉效果很棒，插件式架构，支持各种数据源，是开源监控数据可视化的标杆之作。Grafana 可以直接对接 Prometheus，大部分使用 Prometheus 的用户，也都会使用 Grafana，下面我们就来部署一下。</p><p>我们可以先把 Grafana 下载下来，它分为两个版本，企业版和开源版，开源版本遵照AGPLV3 协议，只要不做二次开发商业化分发，是可以直接使用的。我这里就下载了开源版</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>本，选择 tar.gz 包，下载之后解压缩，执行 ./bin/grafana-server 即可一键启动，</span></span></code></pre></div><p>Grafana 默认的监听端口是 3000，访问后就可以看到登录页面了，默认的用户名和密码都是admin。</p><p>要看图首先要配置数据源，在菜单位置：Configuration -&gt; Data sources，点击 Add datasource 就能进入数据源类型选择页面，选择 Prometheus，填写 Prometheus 的链接信息，主要是 URL，点击 Save &amp; test 完成数据源配置。</p><p>Grafana 提供了和 Prometheus 看图页面类似的功能，叫做 Explore，我们可以在这个页面点选指标看图。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/04/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/04/8.png" alt=""></a></p><p>但 Explore 功能不是最核心的，我们使用 Grafana，主要是使用 Dashboard 看图。Grafana 社区有很多人制作了各式各样的大盘，以 JSON 格式上传保存在了 grafana.com，我们想要某个 Dashboard，可以先去这个网站搜索一下，看看是否有人分享过，特别方便。因为我们已经部署了 Node-Exporter，那这里就可以直接导入 Node-Exporter 的大盘，大盘 ID 是 1860，写到图中对应的位置，点击 Load，然后选择数据源点击 Import 即可。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/04/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/04/9.png" alt=""></a></p><p>导入成功的话会自动打开 Dashboard，Node-Exporter 的大盘长这个样子。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/04/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/04/10.png" alt=""></a></p><p>走到这个监控看图的部分，我们也走完了整个流程。下面我们对这节课的内容做一个简单总结。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>本讲的核心内容就是演示 Prometheus 生态相关组件的部署。如果你在课程中是一步一步跟我操作下来的，相信你对 Prometheus 这套生态就有了入门级的认识。学完这些内容我们再来看一下 Prometheus 的架构图，和监控系统通用架构图相互做一个印证，加深理解。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/04/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/04/11.png" alt=""></a></p><ul><li>图片来自官网</li></ul><p>图上有两个部分我们没有讲到，一个是 Pushgateway 组件，另一个是 Service discovery 部分。这里我再做一个简单的补充。</p><ul><li><p>Pushgateway：用于接收短生命周期任务的指标上报，是 PUSH 的接收方式。因为Prometheus 主要是 PULL 的方式拉取监控数据，这就要求在拉取的时刻，监控对象得活着，但是很多短周期任务，比如 cronjob，可能半秒就运行结束了，就没法拉取了。为了应对这种情况，才单独做了 Pushgateway 组件作为整个生态的补充。</p></li><li><p>Service discovery：我们演示抓取数据时，是直接在 prometheus.yml 中配置的多个Targets。这种方式虽然简单直观，但是也有弊端，典型的问题就是如果 Targets 是动态变化的，而且变化得比较频繁，那就会造成管理上的灾难。所以 Prometheus 提供了多种服务发现机制，可以动态获取要监控的目标，比如 Kubernetes 的服务发现，可以通过调用kube-apiserver 动态获取到需要监控的目标对象，大幅降低了抓取目标的管理成本。</p></li></ul><p>最后，我把这一讲的内容整理了一张脑图，供你理解和记忆。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/04/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/04/12.png" alt=""></a></p><h2 id="互动时刻" tabindex="-1">互动时刻 <a class="header-anchor" href="#互动时刻" aria-label="Permalink to &quot;互动时刻&quot;">​</a></h2><p>监控数据的获取，有推（PUSH）拉（PULL）两种模式，不是非黑即白的，不同的场景选择不同的方式，本讲我们在介绍 Pushgateway 模块时提到了一些选型的依据，你知道推拉两种模式的其他优缺点和适用场景吗？欢迎留言分享，也欢迎你把今天的内容分享给你身边的朋友，邀他一起学习。我们下节课再见！</p>`,84)])])}const k=a(t,[["render",p]]);export{g as __pageData,k as default};
